//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay before the retry at zero-based `retry_index`.
    pub fn delay_for_retry(&self, retry_index: u32) -> u64 {
        if self.base_delay_ms >= self.max_delay_ms {
            return self.max_delay_ms;
        }

        let shift = retry_index.min(u64::BITS - 1);
        self.base_delay_ms
            .checked_shl(shift)
            .unwrap_or(self.max_delay_ms)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_saturates_without_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };

        assert_eq!(config.delay_for_retry(0), 10);
        assert_eq!(config.delay_for_retry(3), 80);
        assert_eq!(config.delay_for_retry(4), 100);
        assert_eq!(config.delay_for_retry(u32::MAX), 100);
    }
}

